INSERT INTO `tournament_match_summaries` (`id`,`event_id`,`round`,`best_of`,`leader_one_code`,`archetype_one`,`player_one_name`,`leader_two_code`,`archetype_two`,`player_two_name`,`score_one`,`score_two`,`winner_leader_code`,`winner_side`,`summary`,`source_name`,`source_url`,`evidence_status`) VALUES
('utrecht-2026-final-enel-robin','utrecht-eu-finals-2026','Grand Final',3,'OP15-058','Purple Enel',NULL,'OP09-062','Purple/Yellow Nico Robin',NULL,2,1,'OP15-058',1,'Purple Enel wins the Utrecht EU Finals 2–1. Game 1: Robin goes first, ramps through leader banish, and eventually plays 10-cost Big Mom to heal and turn trigger bodies into 8k attackers. Enel’s Senior Pink, Vergo, K-10, and El Thor line threatens a final 12k attack, but Robin counters exactly enough and survives; Enel concedes. Game 2: Enel builds Shura, Pudding, and other vassals while Robin develops searchers and ramps. Robin uses Big Mom aggressively to push Enel to zero life, but Enel holds counter, survives the attack turn, then removes key attackers and wins on the return turn. Game 3: Robin ramps and resolves Big Mom, Sweet 3 Generals, and additional large threats, repeatedly healing and rebuilding her board. Enel manages resources carefully, using Lightning Dragon, El Thor, K-10, blockers, and event counters to survive. Robin eventually taps out for Big Mom and a wide board; Enel uses Mamaragan, El Thor, K-10, and leader ability to create an 8k leader attack followed by a 9k Pudding attack. Robin’s remaining counter is not enough, and Enel wins the deciding game and the title.','User-provided video analysis summary','https://www.youtube.com/watch?v=qgwRa20C3lE','VERIFIED'),
('utrecht-2026-top16-luffy-mihawk','utrecht-eu-finals-2026','Top 16',3,'OP17-079','Black Elbaf Monkey.D.Luffy',NULL,'OP14-020','Green Dracule Mihawk',NULL,2,1,'OP17-079',1,'Black Elbaf Luffy wins 2–1 and eliminates Green Mihawk. Game 1: Mihawk curves Kin’emon, Perona, Coffin Boat, and Samurai but chooses to starve Luffy. Luffy develops Usopp, Rodo, Saul, Nami, and Sanji without needing life cards, then uses Kong Gun to remove Mihawk’s Oden and Law. An 8-cost Luffy reanimates two-cost bodies and helps set up a 12k Robin attack at zero life that Mihawk cannot counter. Game 2: Luffy again develops Usopp, Saul, and Kong Gun, but Mihawk has For Fun and Trichiliocosm to survive Luffy’s final push at one life. Back-to-back 10-cost Shanks rest Luffy’s blockers and close the game for Mihawk. Game 3: Luffy rebuilds his draw engine through Sanji, Gird, and Usopp, then develops 8-cost Luffy and Loki. Kong Gun clears Mihawk’s board, while Ground Death and counter cards help Luffy survive the Shanks attacks at zero life. Luffy returns on the next turn and lands the final attack, advancing from Top 16.','User-provided video analysis summary','https://www.youtube.com/watch?v=qgwRa20C3lE','VERIFIED');
